<?php
namespace App\Domain\Workflow\Handlers;
use App\Domain\Workflow\{ActionHandler,ActionResult};use InvalidArgumentException;
final class TransformAction implements ActionHandler {public function type():string{return 'transform';}public function validateConfig(array $config):void{if(!isset($config['operations'])||!is_array($config['operations']))throw new InvalidArgumentException('operations is required');}public function execute(array $config,array $context,string $idempotencyKey):ActionResult{$this->validateConfig($config);$data=$context;foreach($config['operations'] as $op){$key=$op['key']??null;if(!$key)continue;$data[$key]=match($op['op']??'set'){'set'=>$op['value']??null,'copy'=>$data[$op['from']??'']??null,'upper'=>(function_exists('mb_strtoupper') ? mb_strtoupper((string)($data[$key]??'')) : strtoupper((string)($data[$key]??''))),'lower'=>(function_exists('mb_strtolower') ? mb_strtolower((string)($data[$key]??'')) : strtolower((string)($data[$key]??''))),default=>throw new InvalidArgumentException('Unknown transform op')};}return new ActionResult($data);}}
